/* Generate function */
void codegen_function(Codegen *cg, FuncDef *func) {
    if (func->is_extern) {
        /* extern functions are not generated (they come from #include) */
        return;
    }

    const char *ret_str = fl_type_to_c_string(func->return_type);

    /* Special case: main() must return int in C */
    if (strcmp(func->name, "main") == 0) {
        ret_str = "int";
    }

    codegen_emit(cg, "%s %s(", ret_str, func->name);

    if (func->param_count == 0) {
        fputs("void", cg->out);
    } else {
        for (int i = 0; i < func->param_count; i++) {
            if (i > 0) fputs(", ", cg->out);
            const char *ptype = fl_type_to_c_string(func->param_types[i]);
            fprintf(cg->out, "%s %s", ptype, func->param_names[i]);
        }
    }

    fputs(") {\n", cg->out);
    codegen_indent(cg);
    codegen_statement(cg, func->body);
    codegen_unindent(cg);
    codegen_emit(cg, "}\n\n");
}

/* Check if function is from standard C library (already declared by #include) */
static int is_stdlib_function(const char *name) {
    static const char *stdlib_funcs[] = {
        "printf", "scanf", "puts", "gets", "fgets", "fputs", "fopen", "fclose",
        "fread", "fwrite", "fflush", "fseek", "ftell", "rewind", "remove", "rename",
        "malloc", "free", "calloc", "realloc", "memcpy", "memset", "strcpy", "strcat",
        "strlen", "strcmp", "strstr", "strchr", "sprintf", "fprintf", "snprintf",
        "abs", "labs", "atoi", "atol", "atof", "rand", "srand", "qsort", "bsearch",
        "exit", "abort", "getenv", "system", "sleep", "time", "clock", "difftime",
        NULL
    };

    for (int i = 0; stdlib_funcs[i]; i++) {
        if (strcmp(name, stdlib_funcs[i]) == 0) {
            return 1;
        }
    }
    return 0;
}

/* Generate program */
void codegen_program(Codegen *cg, Program *prog) {
    codegen_emit_preamble(cg, prog);

    /* Emit struct definitions first */
    if (prog->struct_defs) {
        for (int i = 0; i < prog->struct_count; i++) {
            codegen_statement(cg, prog->struct_defs[i]);
        }
        if (prog->struct_count > 0) {
            fputs("\n", cg->out);  /* blank line after structs */
        }
    }

    /* Emit extern function declarations (skip stdlib functions) */
    int extern_count = 0;
    for (int i = 0; i < prog->func_count; i++) {
        if (prog->functions[i]->is_extern && !is_stdlib_function(prog->functions[i]->name)) {
            FuncDef *f = prog->functions[i];
            const char *rtype = fl_type_to_c_string(f->return_type);
            codegen_emit(cg, "%s %s(", rtype, f->name);

            for (int j = 0; j < f->param_count; j++) {
                if (j > 0) fputs(", ", cg->out);
                const char *ptype = fl_type_to_c_string(f->param_types[j]);
                fprintf(cg->out, "%s", ptype);
            }

            fputs(");\n", cg->out);
            extern_count++;
        }
    }

    if (extern_count > 0) {
        fputs("\n", cg->out);  /* blank line after externs */
    }

    /* Emit function definitions */
    for (int i = 0; i < prog->func_count; i++) {
        if (!prog->functions[i]->is_extern) {
            codegen_function(cg, prog->functions[i]);
        }
    }

    codegen_emit_end(cg);
}

/* Emit includes */
void codegen_emit_preamble(Codegen *cg, Program *prog) {
    fputs("#include <stdio.h>\n", cg->out);
    fputs("#include <stdlib.h>\n", cg->out);
    fputs("#include <string.h>\n", cg->out);

    /* Emit user-defined includes */
    if (prog && prog->includes) {
        for (int i = 0; i < prog->include_count; i++) {
            fprintf(cg->out, "#include %s\n", prog->includes[i]);
        }
    }

    fputs("\n", cg->out);
}

void codegen_emit_end(Codegen *cg) {
    /* Nothing special needed at end */
}

/* Legacy helper functions */

void codegen_var_decl(Codegen *cg, const char *name, FlType *ty,
                      const char *init_expr) {
    const char *c_type = fl_type_to_c_string(ty);

    if (init_expr) {
        codegen_emit(cg, "%s %s = %s;", c_type, name, init_expr);
    } else {
        codegen_emit(cg, "%s %s;", c_type, name);
    }
    codegen_newline(cg);
}

void codegen_func_decl(Codegen *cg, const char *name, FlType *ret_ty,
                       const char **param_names, FlType **param_types,
                       int param_count) {
    const char *ret_str = fl_type_to_c_string(ret_ty);

    codegen_emit(cg, "%s %s(", ret_str, name);

    if (param_count == 0) {
        fputs("void", cg->out);
    } else {
        for (int i = 0; i < param_count; i++) {
            if (i > 0) fputs(", ", cg->out);
            const char *param_type_str = fl_type_to_c_string(param_types[i]);
            fprintf(cg->out, "%s %s", param_type_str, param_names[i]);
        }
    }

    fputs(")", cg->out);
}

void codegen_func_begin(Codegen *cg) {
    fputs(" {\n", cg->out);
    codegen_indent(cg);
}

void codegen_func_end(Codegen *cg) {
    codegen_unindent(cg);
    codegen_emit(cg, "}\n");
    codegen_newline(cg);
}

void codegen_return(Codegen *cg, const char *expr) {
    if (expr) {
        codegen_emit(cg, "return %s;", expr);
    } else {
        codegen_emit(cg, "return;");
    }
    codegen_newline(cg);
