            codegen_indent(cg);
            codegen_statement(cg, stmt->for_stmt.body);
            codegen_unindent(cg);
            codegen_emit(cg, "}\n");
            break;
        }

        case STMT_BLOCK: {
            for (int i = 0; i < stmt->block.count; i++) {
