#include "../include/ast.h"
#include <stdlib.h>
#include <string.h>

/* ---- Expression Constructors ---- */

Expr *expr_literal_int(long long value) {
    Expr *e = calloc(1, sizeof(Expr));
    e->kind = EXPR_LITERAL;
    e->type = fl_type_i64();
    e->lit_int.ival = value;
    return e;
}

Expr *expr_literal_float(double value) {
    Expr *e = calloc(1, sizeof(Expr));
    e->kind = EXPR_LITERAL;
    e->type = fl_type_f64();
    e->lit_float.fval = value;
    return e;
}

Expr *expr_literal_string(const char *value) {
    Expr *e = calloc(1, sizeof(Expr));
    e->kind = EXPR_LITERAL;
    e->type = fl_type_string();
    e->lit_string.sval = strdup(value);
    return e;
}

Expr *expr_var(const char *name) {
    Expr *e = calloc(1, sizeof(Expr));
    e->kind = EXPR_VAR;
    e->var.name = strdup(name);
    return e;
}

Expr *expr_binary(Expr *left, Expr *right, const char *op) {
    Expr *e = calloc(1, sizeof(Expr));
    e->kind = EXPR_BINARY;
    e->binary.left = left;
    e->binary.right = right;
    e->binary.op = strdup(op);
    return e;
}

Expr *expr_unary(Expr *operand, const char *op) {
    Expr *e = calloc(1, sizeof(Expr));
    e->kind = EXPR_UNARY;
    e->unary.operand = operand;
    e->unary.op = strdup(op);
    return e;
}

Expr *expr_call(const char *func_name, Expr **args, int arg_count) {
    Expr *e = calloc(1, sizeof(Expr));
    e->kind = EXPR_CALL;
    e->call.func_name = strdup(func_name);
    e->call.arg_count = arg_count;

    /* Allocate and copy args array */
    if (arg_count > 0 && args) {
        e->call.args = malloc(sizeof(Expr *) * arg_count);
        for (int i = 0; i < arg_count; i++) {
            e->call.args[i] = args[i];
        }
    } else {
        e->call.args = NULL;
    }

    return e;
}

Expr *expr_index(Expr *array, Expr *index) {
    Expr *e = calloc(1, sizeof(Expr));
    e->kind = EXPR_INDEX;
    e->index.array = array;
    e->index.index = index;
    return e;
}

Expr *expr_member(Expr *object, const char *field) {
    Expr *e = calloc(1, sizeof(Expr));
    e->kind = EXPR_MEMBER;
    e->member.object = object;
    e->member.field = strdup(field);
    return e;
}

/* ---- Statement Constructors ---- */

Stmt *stmt_var_decl(const char *name, FlType *type, Expr *init) {
    Stmt *s = calloc(1, sizeof(Stmt));
    s->kind = STMT_VAR_DECL;
    s->var_decl.name = strdup(name);
    s->var_decl.type = type;
    s->var_decl.init = init;
    return s;
}

Stmt *stmt_return(Expr *value) {
    Stmt *s = calloc(1, sizeof(Stmt));
    s->kind = STMT_RETURN;
    s->ret.value = value;
    return s;
}

Stmt *stmt_if(Expr *cond, Stmt *then_b, Stmt *else_b) {
    Stmt *s = calloc(1, sizeof(Stmt));
    s->kind = STMT_IF;
    s->if_stmt.condition = cond;
    s->if_stmt.then_body = then_b;
    s->if_stmt.else_body = else_b;
    return s;
}

Stmt *stmt_while(Expr *cond, Stmt *body) {
    Stmt *s = calloc(1, sizeof(Stmt));
    s->kind = STMT_WHILE;
    s->while_stmt.condition = cond;
    s->while_stmt.body = body;
    return s;
}

Stmt *stmt_for(const char *var, Expr *start, Expr *end, Stmt *body) {
    Stmt *s = calloc(1, sizeof(Stmt));
    s->kind = STMT_FOR;
    s->for_stmt.var_name = strdup(var);
    s->for_stmt.start = start;
    s->for_stmt.end = end;
    s->for_stmt.body = body;
    return s;
}

Stmt *stmt_block(Stmt **stmts, int count) {
    Stmt *s = calloc(1, sizeof(Stmt));
    s->kind = STMT_BLOCK;
    s->block.stmts = stmts;
    s->block.count = count;
    return s;
}

Stmt *stmt_expr(Expr *expr) {
    Stmt *s = calloc(1, sizeof(Stmt));
    s->kind = STMT_EXPR;
    s->expr = expr;
    return s;
}

/* ---- Struct Support ---- */

StructField *struct_field_new(const char *name, FlType *type) {
    StructField *field = calloc(1, sizeof(StructField));
    field->name = strdup(name);
    field->type = type;
    return field;
}

Stmt *stmt_struct_def(const char *name, StructField **fields, int field_count) {
    Stmt *s = calloc(1, sizeof(Stmt));
    s->kind = STMT_STRUCT_DEF;
    s->struct_def.name = strdup(name);
    s->struct_def.fields = fields;
    s->struct_def.field_count = field_count;
    return s;
}

/* ---- Function Definition ---- */

FuncDef *func_def_new(const char *name,
                      const char **param_names,
                      FlType **param_types,
                      int param_count,
                      FlType *return_type,
                      Stmt *body) {
    FuncDef *f = calloc(1, sizeof(FuncDef));
    f->name = strdup(name);
    f->param_names = param_names;
    f->param_types = param_types;
    f->param_count = param_count;
    f->return_type = return_type;
    f->body = body;
    return f;
}

Program *program_new(FuncDef **funcs, int func_count) {
    Program *p = calloc(1, sizeof(Program));
    p->functions = funcs;
    p->func_count = func_count;
    p->struct_defs = NULL;
    p->struct_count = 0;
    return p;
}

/* Set struct definitions in a Program */
void program_set_structs(Program *prog, Stmt **structs, int count) {
    prog->struct_defs = structs;
    prog->struct_count = count;
}

/* ---- Cleanup ---- */

void expr_free(Expr *e) {
    if (!e) return;

    switch (e->kind) {
        case EXPR_VAR:
            free((void *)e->var.name);
            break;
        case EXPR_BINARY:
            expr_free(e->binary.left);
            expr_free(e->binary.right);
            free((void *)e->binary.op);
            break;
        case EXPR_UNARY:
            expr_free(e->unary.operand);
            free((void *)e->unary.op);
            break;
        case EXPR_CALL:
            for (int i = 0; i < e->call.arg_count; i++) {
                expr_free(e->call.args[i]);
            }
            free(e->call.args);
            free((void *)e->call.func_name);
            break;
        case EXPR_INDEX:
            expr_free(e->index.array);
            expr_free(e->index.index);
            break;
        case EXPR_MEMBER:
            expr_free(e->member.object);
            free((void *)e->member.field);
            break;
        case EXPR_LITERAL:
            if (e->type && e->type->kind == FL_TYPE_STRING) {
                free((void *)e->lit_string.sval);
            }
            break;
        default:
            break;
    }

    fl_type_free(e->type);
    free(e);
}

void stmt_free(Stmt *s) {
    if (!s) return;

    switch (s->kind) {
        case STMT_VAR_DECL:
            free((void *)s->var_decl.name);
            expr_free(s->var_decl.init);
            fl_type_free(s->var_decl.type);
            break;
        case STMT_EXPR:
            expr_free(s->expr);
            break;
        case STMT_RETURN:
            expr_free(s->ret.value);
            break;
        case STMT_IF:
            expr_free(s->if_stmt.condition);
            stmt_free(s->if_stmt.then_body);
            stmt_free(s->if_stmt.else_body);
            break;
        case STMT_WHILE:
            expr_free(s->while_stmt.condition);
            stmt_free(s->while_stmt.body);
            break;
        case STMT_FOR:
            free((void *)s->for_stmt.var_name);
            expr_free(s->for_stmt.start);
            expr_free(s->for_stmt.end);
            stmt_free(s->for_stmt.body);
            break;
        case STMT_BLOCK:
            for (int i = 0; i < s->block.count; i++) {
                stmt_free(s->block.stmts[i]);
            }
            free(s->block.stmts);
            break;
        case STMT_STRUCT_DEF:
            free((void *)s->struct_def.name);
            for (int i = 0; i < s->struct_def.field_count; i++) {
                if (s->struct_def.fields[i]) {
                    free((void *)s->struct_def.fields[i]->name);
                    fl_type_free(s->struct_def.fields[i]->type);
                    free(s->struct_def.fields[i]);
                }
            }
            free(s->struct_def.fields);
            break;
        default:
            break;
    }

    free(s);
}

void func_def_free(FuncDef *f) {
    if (!f) return;

    free((void *)f->name);
    free(f->param_names);
    for (int i = 0; i < f->param_count; i++) {
        fl_type_free(f->param_types[i]);
    }
    free(f->param_types);
    fl_type_free(f->return_type);
    stmt_free(f->body);
    free(f);
}

void program_free(Program *p) {
    if (!p) return;

    for (int i = 0; i < p->func_count; i++) {
        func_def_free(p->functions[i]);
    }
    free(p->functions);

    for (int i = 0; i < p->struct_count; i++) {
        stmt_free(p->struct_defs[i]);
    }
    free(p->struct_defs);

    free(p);
}

