/* --- E2E: 전체 함수 생성 및 gcc 컴파일 --- */
void test_e2e_simple_function(void) {
    /* fn add(a: i32, b: i32) -> i32 { return a + b; } */
    Expr *sum = expr_binary(expr_var("a"), expr_var("b"), "+");
    Stmt *body = stmt_return(sum);

    const char *param_names[] = { "a", "b" };
    FlType *param_types[] = { fl_type_i32(), fl_type_i32() };
    FuncDef *func = func_def_new("add", param_names, param_types, 2, fl_type_i32(), body);

    FuncDef *funcs[] = { func };
    Program *prog = program_new(funcs, 1);

    FILE *f = fopen("/tmp/test_e2e_add.c", "w");
    Codegen *cg = codegen_new(f);
    codegen_program(cg, prog);
    fclose(f);
    codegen_free(cg);

    FILE *check = fopen("/tmp/test_e2e_add.c", "r");
    char content[1024] = {0};
    fread(content, 1, sizeof(content)-1, check);
    fclose(check);

    TEST_ASSERT(strstr(content, "int add"), "should have int add");
    TEST_ASSERT(strstr(content, "int a"), "should have int a param");
    TEST_ASSERT(strstr(content, "return"), "should have return");
    program_free(prog);
}

void test_e2e_fibonacci_structure(void) {
    /* fn fib(n: i32) -> i32 { if (n <= 1) return n; return fib(n-1) + fib(n-2); } */
    Expr *cond = expr_binary(expr_var("n"), expr_literal_int(1), "<=");
    Stmt *base = stmt_return(expr_var("n"));
    Stmt *if_s = stmt_if(cond, base, NULL);

    Expr *n1 = expr_binary(expr_var("n"), expr_literal_int(1), "-");
    Expr *n2 = expr_binary(expr_var("n"), expr_literal_int(2), "-");
    Expr *args1[] = { n1 };
    Expr *args2[] = { n2 };
    Expr *call1 = expr_call("fib", args1, 1);
    Expr *call2 = expr_call("fib", args2, 1);
    Expr *result = expr_binary(call1, call2, "+");
    Stmt *rec_ret = stmt_return(result);

    Stmt *stmts[] = { if_s, rec_ret };
    Stmt *body = stmt_block(stmts, 2);

    const char *param_names[] = { "n" };
    FlType *param_types[] = { fl_type_i32() };
    FuncDef *func = func_def_new("fib", param_names, param_types, 1, fl_type_i32(), body);

    FuncDef *funcs[] = { func };
    Program *prog = program_new(funcs, 1);

    FILE *f = fopen("/tmp/test_e2e_fib.c", "w");
    Codegen *cg = codegen_new(f);
    codegen_program(cg, prog);
    fclose(f);
    codegen_free(cg);

    FILE *check = fopen("/tmp/test_e2e_fib.c", "r");
    char content[2048] = {0};
    fread(content, 1, sizeof(content)-1, check);
    fclose(check);

    TEST_ASSERT(strstr(content, "int fib"), "should have int fib");
    TEST_ASSERT(strstr(content, "if"), "should have if");
    TEST_ASSERT(strstr(content, "fib("), "should have recursive call");
    program_free(prog);
}

void test_e2e_gcc_compile(void) {
    /* 앞선 E2E 테스트가 생성한 fib 파일이 실제 gcc로 컴파일되는지 검증 */
    int ret = system("gcc -std=c99 /tmp/test_e2e_fib.c -o /tmp/test_e2e_fib_bin 2>/dev/null");
    TEST_ASSERT(ret == 0, "generated fib C code should compile with gcc");
}

